  "content": "package com.confighub.platform.service;

import com.confighub.platform.dto.ApiResponse;
import com.confighub.platform.entity.Config;
import com.confighub.platform.entity.ImportRecord;
import com.confighub.platform.entity.Namespace;
import com.confighub.platform.mapper.ConfigMapper;
import com.confighub.platform.mapper.ImportRecordMapper;
import com.confighub.platform.mapper.NamespaceMapper;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import org.yaml.snakeyaml.DumperOptions;
import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import java.util.zip.ZipInputStream;
import java.util.zip.ZipOutputStream;

@Service
public class ImportExportService {

    private static final String METADATA_ENTRY = "_metadata.yml";
    private static final String DEFAULT_GROUP = "DEFAULT_GROUP";
    private static final String DEFAULT_FORMAT = "YAML";

    private final ConfigMapper configMapper;
    private final NamespaceMapper namespaceMapper;
    private final ImportRecordMapper importRecordMapper;

    public ImportExportService(ConfigMapper configMapper, NamespaceMapper namespaceMapper,
                               ImportRecordMapper importRecordMapper) {
        this.configMapper = configMapper;
        this.namespaceMapper = namespaceMapper;
        this.importRecordMapper = importRecordMapper;
    }

    public byte[] exportConfigs(Long namespaceId) {
        Namespace namespace = namespaceMapper.findById(namespaceId);
        List<Config> configs = configMapper.findByNamespaceId(namespaceId);
        Yaml yaml = newYamlDumper();

        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(bos, StandardCharsets.UTF_8)) {
            Map<String, Object> metadata = new LinkedHashMap<>();
            metadata.put("exportTime", LocalDateTime.now().toString());
            metadata.put("namespace", namespace != null ? namespace.getName() : "unknown");
            metadata.put("configCount", configs.size());
            metadata.put("version", 1);
            writeEntry(zos, METADATA_ENTRY, yaml.dump(metadata));

            for (Config config : configs) {
                String entryName = config.getGroupName() + "_" + config.getDataId();
                if (!entryName.endsWith(".yml") && !entryName.endsWith(".yaml")) {
                    entryName += ".yml";
                }
                Map<String, Object> entryData = new LinkedHashMap<>();
                entryData.put("dataId", config.getDataId());
                entryData.put("groupName", config.getGroupName());
                entryData.put("format", config.getFormat());
                entryData.put("content", config.getContent());
                writeEntry(zos, entryName, yaml.dump(entryData));
            }
        } catch (IOException e) {
            throw new RuntimeException("导出配置失败", e);
        }
        return bos.toByteArray();
    }

    public ApiResponse<?> importConfigs(Long namespaceId, Long userId, MultipartFile file) {
        int importedCount = 0;
        int failedCount = 0;
        try {
            byte[] bytes = file.getBytes();
            // ZipInputStream silently yields no entries for non-ZIP data, so reject it explicitly
            if (bytes.length < 4 || bytes[0] != 'P' || bytes[1] != 'K') {
                throw new ZipException("Not a ZIP archive");
            }
            try (ZipInputStream zis = new ZipInputStream(new ByteArrayInputStream(bytes),
                    StandardCharsets.UTF_8)) {
                ZipEntry entry;
                while ((entry = zis.getNextEntry()) != null) {
                    String name = entry.getName();
                    if (entry.isDirectory() || METADATA_ENTRY.equals(name)
                            || !(name.endsWith(".yml") || name.endsWith(".yaml"))) {
                        continue;
                    }
                    try {
                        String text = new String(zis.readAllBytes(), StandardCharsets.UTF_8);
                        if (importEntry(namespaceId, text)) {
                            importedCount++;
                        } else {
                            failedCount++;
                        }
                    } catch (Exception e) {
                        failedCount++;
                    }
                }
            }
        } catch (Exception e) {
            ImportRecord record = saveRecord(namespaceId, userId, file.getOriginalFilename(),
                    "FAILED", 0, 0);
            return ApiResponse.success("导入失败", record);
        }

        String status;
        if (failedCount == 0) {
            status = "SUCCESS";
        } else if (importedCount > 0) {
            status = "PARTIAL";
        } else {
            status = "FAILED";
        }
        ImportRecord record = saveRecord(namespaceId, userId, file.getOriginalFilename(),
                status, importedCount, failedCount);
        String message = "SUCCESS".equals(status) ? "导入完成" : "部分导入成功";
        return ApiResponse.success(message, record);
    }

    public ApiResponse<?> getImportRecords(Long namespaceId) {
        List<ImportRecord> records = importRecordMapper.findByNamespaceId(namespaceId);
        return ApiResponse.success(records);
    }

    private boolean importEntry(Long namespaceId, String text) {
        Map<String, Object> data = parseYamlMapping(text);
        if (data == null) {
            return false;
        }
        String dataId = asString(data.get("dataId"));
        String content = asString(data.get("content"));
        if (dataId == null || content == null) {
            return false;
        }
        String groupName = data.get("groupName") != null ? asString(data.get("groupName")) : DEFAULT_GROUP;
